<template>
	<div class="Register page">
<!-- 		<div class="box" @focusout="focusout" @focusin="focusin">
			<div class="cell margin-top-10">
				<div class="col-4">
					<img class="title icon-back" @click="go('back')" src="@/assets/img/row-left.png">
				</div>
				<div class="col-16">
					<img class="logo title" src="@/assets/img/register.png">
				</div>
				<div class="col-4"></div>
			</div> -->
			<div class="box" @focusout="focusout" @focusin="focusin">
				<div class="cell padding-10 margin-bottom-10">
					<img class="back" @click="go('back')" src="@/assets/img/row-left.png" alt="">
					<div class="title">注册账号</div>
					<div class="back"></div>
				</div>
			<div class="cell">
				<div class="input bottom-line code-box" ref="input">
					<img class="icon pre-icon" src="@/assets/img/number.png">
					<input type="tel" pattern="[0-9]*" v-model="username" name="username" readonly @click="focusin"
						placeholder="请输入手机号码" />
					<img class="icon end-icon transition-all" style="opacity: 0;" src="@/assets/img/row-up.png" />
					<img class="icon input-focus" :style="{opacity:(username.length>0?1:0)}"
						@click="clearInput('username')" src="@/assets/img/close.png" />
				</div>
			</div>
			<div class="cell">
				<div class="input bottom-line code-box">
					<img class="icon pre-icon" src="@/assets/img/square.png">
					<input v-model="code" placeholder="请输入验证码" name="code" readonly @click="focusin" type="text" />
					<img class="icon input-focus" :style="{opacity:(code.length>0?1:0)}" @click="clearInput('code')"
						src="@/assets/img/close.png">
					<div class="btn btn-grey border-red font-color-red code end-icon" @click="getCode" v-show="time<=0">
						获取验证码
					</div>
					<div class="btn btn-grey code end-icon" v-show="time>0">
						重新获取({{time}}S)
					</div>
				</div>
			</div>
			<div class="cell">
				<div class="input bottom-line code-box">
					<img class="icon pre-icon" src="@/assets/img/lock.png">
					<input class="" v-model="password" :placeholder="passwordPlaceHolder" name="password" readonly
						@click="focusin" :type="passwordType" />
					<img class="icon input-focus" :style="{opacity:(password.length>0?1:0)}"
						@click="clearInput('password')" src="@/assets/img/close.png">
					<img class="icon end-icon input-focus" v-show="passwordType=='password'"
						@click="passwordType='text'" src="@/assets/img/unview.png">
					<img class="icon end-icon" v-show="passwordType!='password'" @click="passwordType='password'"
						src="@/assets/img/view.png">
				</div>
			</div>
			<div class="cell">
				<img @click.stop="checked=!checked" v-show="checked" class="icon check" src="@/assets/img/check-red.png">
				<img @click.stop="checked=!checked" v-show="!checked" class="icon check" src="@/assets/img/uncheck-red.png">
				<span>&nbsp;&nbsp;</span><span class="text-left check-text">我已阅读并同意《<a class="font-color-red"
						@click.stop="go('/agreement/userAgreement')">用户协议</a>》和《<a class="font-color-red"
						@click.stop="go('/agreement/privacyPolicy')">隐私政策</a>》</span>
			</div>
			<br />
			<div class="btn-box margin-top-10">
				<div class="col-24 padding-6">
					<div class="btn bg-red btn-primary color-white" @click="submit">确认</div>
				</div>
			</div>
			<br />
			<br />
		</div>
	</div>
</template>

<script>
	import {
		ref
	} from 'vue'
	import bridge from '@/assets/js/bridge'
	export default {
		name: 'Register',
		setup() {
			return {
				username: ref(''),
				password: ref(''),
				code: ref(''),
				time: ref(0),
				timer: ref(null),
				in: ref(false),
				passwordType: ref('password'),
				checked: ref(false),
			}
		},
		mounted() {
			this.inputFocus()
		},
		methods: {
			async getCode() {
				if (!this.username) {
					return this.$toast.show('手机号不能为空')
				}
				if (this.username.length > 11) {
					return this.$toast.show('手机号过长')
				}
				if (!this.$check.isPhone(this.username)) {
					return this.$toast.show('手机号格式错误')
				}
				clearInterval(this.timer)
				if (this.time <= 0) {
					this.time = 60
					this.timer = setInterval(() => {
						this.time--
						if (this.time <= 0) {
							clearInterval(this.timer)
						}
					}, 1000)

					let res = await this.$store.dispatch('register/getCode', {
						phone: this.username,
						type: 1
					})
					if (this.$check.ok(res)) {
						this.$toast.show('验证码获取成功')
					} else {
						clearInterval(this.timer)
						this.time = 0
					}
				}
			},
			async submit() {
				if (!this.username) {
					return this.$toast.show('手机号不能为空')
				}
				if (!this.password) {
					return this.$toast.show('密码不能为空')
				}
				if (this.password.length < 6 || this.password.length > 20) {
					return this.$toast.show('密码长度需大于6位小于20位')
				}
				if (!this.code) {
					return this.$toast.show('验证码不能为空')
				}
				if (!this.checked) {
					return this.$toast.show('请勾选下方协议')
				}
				let res = await this.$store.dispatch('register/register', {
					phone: this.username,
					password: this.password,
					smsCode: this.code
				})
				if (this.$check.ok(res)) {
					let loginType = this.LoginTypeDic['phoneLogin']
					this.$store.commit('SET_LOGIN_REMBER', {
						username: this.username,
						password: this.password,
						loginType: loginType,
						checked: false
					})
					let tempData = {
						loginName: "+86" + this.username,
						phone: "+86" + this.username,
						password: this.password,
						loginType: loginType
					}
					this.username = ''
					this.password = ''
					this.code = ''
					this.$toast.show('成功')
					let param = Object.assign({
						loginType: loginType
					}, res[0].data.data)

					this.$store.commit('login/PUSH_USER_HISTORY', Object.assign(param, tempData))
					this.$store.commit('SET_USER_INFO', param)
					if (this.userInfo.isForceAuthentication && !this.userInfo.isAuthentication) {
						return this.go('/auth')
					}
					if (this.userInfo.isForceBindPhone && !this.userInfo.phone) {
						return this.go('/bind')
					}
					bridge.postLoginSuccess('registeredSuccess', param)
				} else {
					bridge.postLoginSuccess('registeredFailed', res)
				}
			},
		}
	}
</script>

<style scoped>
	.Register {
		display: table-cell;
		text-align: center;
		vertical-align: middle;
	}
</style>
